-- Extend finite shared configuration and tracking catalogs without rewriting prior engines.
create or replace function boss_private.tracking_selection(sport text,preset text,selected jsonb default'[]',quick jsonb default null)returns jsonb
language plpgsql stable security definer set search_path=''as $$
declare enabled text[];seed text[];ordered text[];k text;deps text[];d public.game_stat_catalog_items;changed boolean;begin
 if sport not in('basketball','soccer','football','volleyball','baseball','softball')or sport is null or preset is null or preset not in('score_only','essential','standard','advanced','full','custom')or jsonb_typeof(selected)is distinct from'array'or jsonb_array_length(selected)>128 then raise exception 'Invalid tracking selection'using errcode='PT422';end if;
 if preset<>'custom'and jsonb_array_length(selected)>0 then raise exception 'Preset contains custom selections'using errcode='PT422';end if;
 if preset='custom'then select coalesce(array_agg(value),'{}')into seed from jsonb_array_elements_text(selected);
 elsif preset='score_only'then seed:='{}';
 elsif preset='essential'then seed:=case sport
 when'basketball'then array['player_attribution','assists','offensive_rebounds','defensive_rebounds']
 when'soccer'then array['player_attribution','assists','shots','saves']
 when'football'then array['player_attribution','quick_rush','quick_pass_complete','quick_pass_incomplete']
 when'baseball'then array['player_attribution','baserunning'] when'softball'then array['player_attribution','baserunning'] else array['player_attribution','kills','assists','digs','service_aces','service_errors','solo_blocks','block_assists']end;
 else select array_agg(key order by(definition->>'order')::integer)into seed from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and definition->>'classification'='optional'and(definition->>'available')::boolean;end if;
 if(select count(distinct v)from unnest(seed)v)<>cardinality(seed)then raise exception 'Duplicate tracking selection'using errcode='PT422';end if;
 select array_agg(key order by(definition->>'order')::integer)into enabled from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and definition->>'classification'='required';
 enabled:=coalesce(enabled,'{}')||seed;
 -- Dependency closure has a strict catalog-size bound and no client formulas.
 for iteration in 1..128 loop
 changed:=false;
 foreach k in array enabled loop
 select *into d from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and key=k;
 if not found or not coalesce((d.definition->>'available')::boolean,false)then raise exception 'Unsupported tracking statistic'using errcode='PT422';end if;
 for k in select value from jsonb_array_elements_text(d.definition->'dependencies')loop
 if not k=any(enabled)then enabled:=array_append(enabled,k);changed:=true;end if;end loop;end loop;
 for d in select *from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and definition->>'classification'='derived'loop
 select coalesce(array_agg(value),'{}')into deps from jsonb_array_elements_text(d.definition->'dependencies');
 if cardinality(deps)>0 and deps<@enabled and not d.key=any(enabled)then enabled:=array_append(enabled,d.key);changed:=true;end if;end loop;
 exit when not changed;
 if iteration=128 then raise exception 'Invalid tracking dependencies'using errcode='PT422';end if;
 end loop;
 if quick is null then
 select coalesce(array_agg(x.key order by x.ord),'{}')into ordered from(select s.key,s.ord from unnest(case when sport in('baseball','softball')then array['play_state']||array_remove(seed,'play_state')else seed end)with ordinality s(key,ord)join public.game_stat_catalog_items c on c.sport_key=sport and c.catalog_version='boss-tracking-v1'and c.key=s.key where(c.definition->>'quick_eligible')::boolean order by s.ord limit 8)x;
 else
 if jsonb_typeof(quick)is distinct from'array'or jsonb_array_length(quick)>8 then raise exception 'Invalid Quick Stats'using errcode='PT422';end if;
 select coalesce(array_agg(value),'{}')into ordered from jsonb_array_elements_text(quick);
 end if;
 if(select count(distinct v)from unnest(ordered)v)<>cardinality(ordered)then raise exception 'Duplicate Quick Stats'using errcode='PT422';end if;
 foreach k in array ordered loop
 if not k=any(enabled)or not exists(select 1 from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and key=k and(definition->>'quick_eligible')::boolean)then raise exception 'Invalid Quick Stats'using errcode='PT422';end if;end loop;
 select array_agg(key order by(definition->>'order')::integer)into enabled from public.game_stat_catalog_items where sport_key=sport and catalog_version='boss-tracking-v1'and key=any(enabled);
 return jsonb_build_object('catalog_version','boss-tracking-v1','preset',preset,'enabled',to_jsonb(enabled),'quick',to_jsonb(ordered));
end$$;
create or replace function boss_private.tracking_profile_command(actor uuid,i jsonb,request uuid,replay boolean default false)returns jsonb
language plpgsql volatile security definer set search_path=''as $$
declare p public.game_tracking_profiles;old public.game_tracking_profiles;g public.games;e public.events;
 selection jsonb;before_state jsonb;rid uuid;opid uuid;reason text;begin
 perform boss_private.games_validate(i,array['sport_key','scope_type','organization_id','unit_id','team_id','season_id','game_id','side','expected_profile_version','expected_game_version','preset','enabled','quick','status','ends_at','reason'],array['sport_key','scope_type','expected_profile_version','preset','reason']);
 if i->>'sport_key'not in('basketball','soccer','football','volleyball','baseball','softball')or i->>'scope_type'not in('platform','organization','organization_unit','team','season','game')or jsonb_typeof(i->'expected_profile_version')<>'number'or i->>'expected_profile_version'!~'^[0-9]{1,15}$'then raise exception 'Invalid tracking scope/version'using errcode='PT422';end if;
 p.sport_key:=i->>'sport_key';p.scope_type:=i->>'scope_type';p.organization_id:=(i->>'organization_id')::uuid;p.unit_id:=(i->>'unit_id')::uuid;p.team_id:=(i->>'team_id')::uuid;p.season_id:=(i->>'season_id')::uuid;p.game_id:=(i->>'game_id')::uuid;p.side:=i->>'side';
 if not((p.scope_type='platform'and p.organization_id is null and p.unit_id is null and p.team_id is null and p.season_id is null and p.game_id is null and p.side is null)
 or(p.scope_type='organization'and p.organization_id is not null and p.unit_id is null and p.team_id is null and p.season_id is null and p.game_id is null and p.side is null)
 or(p.scope_type='organization_unit'and p.organization_id is not null and p.unit_id is not null and p.team_id is null and p.season_id is null and p.game_id is null and p.side is null)
 or(p.scope_type='team'and p.organization_id is not null and p.unit_id is null and p.team_id is not null and p.season_id is null and p.game_id is null and p.side is null)
 or(p.scope_type='season'and p.organization_id is not null and p.unit_id is null and p.team_id is not null and p.season_id is not null and p.game_id is null and p.side is null)
 or(p.scope_type='game'and p.organization_id is not null and p.unit_id is null and p.team_id is null and p.season_id is null and p.game_id is not null and p.side in('primary','opponent')))then raise exception 'Invalid tracking scope'using errcode='PT422';end if;
 reason:=i->>'reason';if length(btrim(reason))not between 1 and 500 or reason~'[[:cntrl:]]'then raise exception 'Tracking change reason is required'using errcode='PT422';end if;
 selection:=boss_private.tracking_selection(p.sport_key,i->>'preset',coalesce(i->'enabled','[]'),i->'quick');
 p.status:=coalesce(i->>'status','active');p.ends_at:=(i->>'ends_at')::timestamptz;
 if p.status not in('active','inactive')or p.ends_at is not null and(not isfinite(p.ends_at)or p.ends_at<=clock_timestamp())then raise exception 'Invalid tracking lifecycle'using errcode='PT422';end if;
 -- Fast denial before locks; repeat after all waits and before commit.
 perform boss_private.games_require_live_auth();
 if not boss_private.tracking_scope_allowed(actor,p)then raise exception 'Access denied'using errcode='PT403';end if;
 perform boss_private.tracking_locks(p);
 if p.scope_type='game'then
 select event_id into e.id from public.games where id=p.game_id;
 select *into e from public.events where id=e.id for update;
 select *into g from public.games where id=p.game_id for update;
 perform boss_private.games_lock_authority(actor,g);
 if g.status in('final','canceled','abandoned','postponed')then raise exception 'Game tracking is locked'using errcode='PT409';end if;
 if not i?'expected_game_version'or i->>'expected_game_version'!~'^[0-9]{1,15}$'then raise exception 'Game version is required'using errcode='PT422';end if;
 else
 perform 1 from public.role_assignments where person_id=actor and(organization_id=p.organization_id or scope_type='platform')order by id for share;
 perform 1 from public.organization_memberships where person_id=actor and organization_id=p.organization_id order by id for share;
 perform 1 from public.team_memberships where person_id=actor and organization_id=p.organization_id and team_id=p.team_id order by id for share;
 perform 1 from public.organization_modules where organization_id=p.organization_id order by id for share;
 end if;
 perform boss_private.games_require_live_auth();if not boss_private.tracking_scope_allowed(actor,p)then raise exception 'Access denied'using errcode='PT403';end if;
 select *into old from public.game_tracking_profiles x where x.sport_key=p.sport_key and x.scope_type=p.scope_type and x.organization_id is not distinct from p.organization_id and x.unit_id is not distinct from p.unit_id and x.team_id is not distinct from p.team_id and x.season_id is not distinct from p.season_id and x.game_id is not distinct from p.game_id and x.side is not distinct from p.side for update;
 if replay then return jsonb_build_object('profile_id',old.id,'profile_version',old.version,'game_id',g.id,'organization_id',old.organization_id,'version',coalesce(g.version,old.version),'message','Saved.');end if;
 if coalesce(old.version,0)<>(i->>'expected_profile_version')::bigint or g.id is not null and g.version<>(i->>'expected_game_version')::bigint then raise exception 'Tracking profile changed; reload before saving'using errcode='PT409';end if;
 before_state:=to_jsonb(old);
 if old.id is null then
 insert into public.game_tracking_profiles(sport_key,organization_id,scope_type,unit_id,team_id,season_id,game_id,side,version,status,ends_at)
 values(p.sport_key,p.organization_id,p.scope_type,p.unit_id,p.team_id,p.season_id,p.game_id,p.side,1,p.status,p.ends_at)returning *into p;
 else
 update public.game_tracking_profiles set version=old.version+1,status=p.status,ends_at=coalesce(p.ends_at,old.ends_at)where id=old.id returning *into p;end if;
 insert into public.game_tracking_profile_revisions(profile_id,sport_key,version,catalog_version,selection,actor_person_id,request_id)
 values(p.id,p.sport_key,p.version,'boss-tracking-v1',selection,actor,request)returning id into rid;
 if g.id is not null and exists(select 1 from public.game_tracking_snapshots where game_id=g.id)then
 update public.games set version=g.version+1 where id=g.id returning *into g;
 perform boss_private.tracking_snapshot(g,p.side,g.last_sequence+1);
 opid:=boss_private.games_append(g.id,actor,'tracking.profile.set',request,boss_private.games_core_state(g)||jsonb_build_object('tracking_profile',before_state),jsonb_build_object('tracking_profile_id',p.id,'tracking_revision_id',rid,'reason',reason));
 else
 insert into public.audit_events(organization_id,actor_person_id,actor_auth_user_id,action,resource_type,resource_id,scope_type,scope_id,request_id,before_data,after_data)
 values(p.organization_id,actor,auth.uid(),'tracking.profile.set','game_tracking_profile',p.id,case p.scope_type when'season'then'team'when'game'then'organization'else p.scope_type end,case p.scope_type when'platform'then null when'organization_unit'then p.unit_id when'team'then p.team_id when'season'then p.team_id else p.organization_id end,request,before_state,to_jsonb(p)||jsonb_build_object('revision_id',rid,'selection',selection,'reason',reason));end if;
 perform boss_private.games_require_live_auth();if not boss_private.tracking_scope_allowed(actor,p)then raise exception 'Access denied'using errcode='PT403';end if;
 return jsonb_build_object('profile_id',p.id,'profile_version',p.version,'game_id',g.id,'organization_id',p.organization_id,'version',coalesce(g.version,p.version),'message','Tracking profile saved.');
end$$;
create or replace function boss_private.games_configuration(p_org uuid) returns jsonb language sql stable security definer set search_path='' as $$
 with raw as(select boss_private.coordination_configuration(p_org,'sports') c),keys as(select unnest(array['game_center','game_operations','public_game_center','team_game_management','head_coach_game_management','basketball_live_scoring','basketball_stats','basketball_play_by_play','basketball_lineups','soccer_live_scoring','soccer_stats','soccer_play_by_play','soccer_lineups','football_live_scoring','football_stats','football_play_by_play','football_lineups','volleyball_live_scoring','volleyball_stats','volleyball_play_by_play','volleyball_lineups','baseball_live_scoring','baseball_stats','baseball_play_by_play','baseball_lineups','softball_live_scoring','softball_stats','softball_play_by_play','softball_lineups']) k)
 select jsonb_object_agg(k,case when jsonb_typeof(c->k)='boolean' then c->k else 'false'::jsonb end) from raw cross join keys
$$;
create or replace function boss_private.games_feature(p_org uuid,p_key text,p_configuration jsonb default null) returns boolean language sql volatile security definer set search_path='' as $$
 select boss_private.games_module_live(p_org,'sports') and p_key=any(array['game_center','game_operations','public_game_center','team_game_management','head_coach_game_management','basketball_live_scoring','basketball_stats','basketball_play_by_play','basketball_lineups','soccer_live_scoring','soccer_stats','soccer_play_by_play','soccer_lineups','football_live_scoring','football_stats','football_play_by_play','football_lineups','volleyball_live_scoring','volleyball_stats','volleyball_play_by_play','volleyball_lineups','baseball_live_scoring','baseball_stats','baseball_play_by_play','baseball_lineups','softball_live_scoring','softball_stats','softball_play_by_play','softball_lineups'])
 and coalesce((coalesce(p_configuration,boss_private.games_configuration(p_org))->>'game_center')::boolean,false)
 and coalesce((coalesce(p_configuration,boss_private.games_configuration(p_org))->>p_key)::boolean,false)
$$;
create or replace function boss_private.games_configure(p_actor uuid,i jsonb,p_request uuid,p_replay boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare organization uuid;module public.organization_modules;key text;prior jsonb;after_state jsonb;
 flags text[]:=array['game_center','game_operations','public_game_center','team_game_management','head_coach_game_management','basketball_live_scoring','basketball_stats','basketball_play_by_play','basketball_lineups','soccer_live_scoring','soccer_stats','soccer_play_by_play','soccer_lineups','football_live_scoring','football_stats','football_play_by_play','football_lineups','volleyball_live_scoring','volleyball_stats','volleyball_play_by_play','volleyball_lineups','baseball_live_scoring','baseball_stats','baseball_play_by_play','baseball_lineups','softball_live_scoring','softball_stats','softball_play_by_play','softball_lineups'];begin
 perform boss_private.games_validate(i,array['organization_id','expected_version','configuration'],array['organization_id','expected_version','configuration']);
 if jsonb_typeof(i->'configuration')<>'object' or i->'configuration'='{}'::jsonb then raise exception 'Invalid game configuration' using errcode='PT422';end if;
 for key in select jsonb_object_keys(i->'configuration') loop
 if not key=any(flags) or jsonb_typeof(i->'configuration'->key)<>'boolean' then raise exception 'Invalid game configuration' using errcode='PT422';end if;end loop;
 organization:=(i->>'organization_id')::uuid;
 perform 1 from public.role_assignments assignment where assignment.person_id=p_actor and(assignment.organization_id=organization or assignment.scope_type='platform') order by assignment.id for share;
 perform 1 from public.organization_memberships membership where membership.person_id=p_actor and membership.organization_id=organization order by membership.id for share;
 perform boss_private.games_require_live_auth();
 if p_actor is distinct from boss_private.require_admin_actor() or not boss_private.games_role_permission(p_actor,'organization.manage',organization) then raise exception 'Access denied' using errcode='PT403';end if;
 select membership.* into module from public.organization_modules membership join public.modules catalog on catalog.id=membership.module_id and catalog.key='sports' and catalog.status='active'
 where membership.organization_id=organization and membership.status='active' and membership.starts_at<=clock_timestamp() and(membership.ends_at is null or membership.ends_at>clock_timestamp())
 order by membership.starts_at desc,membership.id desc limit 1 for update of membership;
 perform boss_private.games_require_live_auth();
 if p_actor is distinct from boss_private.require_admin_actor() or not boss_private.games_role_permission(p_actor,'organization.manage',organization) then raise exception 'Access denied' using errcode='PT403';end if;
 if module.id is null or module.status<>'active' or module.starts_at>clock_timestamp() or(module.ends_at is not null and module.ends_at<=clock_timestamp()) then raise exception 'Access denied' using errcode='PT403';end if;
 if p_replay then return jsonb_build_object('game_id',null,'organization_id',organization,'version',module.version,'message','Saved.');end if;
 if module.version<>(i->>'expected_version')::bigint then raise exception 'Sports configuration changed; reload before saving' using errcode='PT409';end if;
 select jsonb_build_object('version',module.version,'configuration',jsonb_object_agg(flag,case when jsonb_typeof(module.configuration->flag)='boolean' then module.configuration->flag else 'false'::jsonb end)) into prior from unnest(flags) flag;
 update public.organization_modules set configuration=configuration||(i->'configuration') where id=module.id returning * into module;
 select jsonb_build_object('version',module.version,'configuration',jsonb_object_agg(flag,case when jsonb_typeof(module.configuration->flag)='boolean' then module.configuration->flag else 'false'::jsonb end)) into after_state from unnest(flags) flag;
 insert into public.audit_events(organization_id,actor_person_id,actor_auth_user_id,action,resource_type,resource_id,scope_type,scope_id,request_id,before_data,after_data)
 values(organization,p_actor,auth.uid(),'games.configure','organization_module',module.id,'organization',organization,p_request,prior,after_state);
 return jsonb_build_object('game_id',null,'organization_id',organization,'version',module.version,'message','Game Center settings saved.');
end$$;
create function boss_private.diamond_engine_identity()returns trigger language plpgsql security definer set search_path=''as $$
declare g public.games;begin
 select *into g from public.games where id=new.game_id for update;
 if g.organization_id is distinct from new.organization_id or g.sport_key is distinct from new.sport_key or new.configuration->>'sport'is distinct from g.sport_key
 or exists(select 1 from public.game_basketball_states where game_id=g.id)or exists(select 1 from public.game_soccer_states where game_id=g.id)
 or exists(select 1 from public.game_football_states where game_id=g.id)or exists(select 1 from public.game_volleyball_states where game_id=g.id)then raise exception 'Wrong Diamond engine identity'using errcode='PT409';end if;return new;
end$$;
create trigger diamond_engine_identity before insert on public.game_diamond_states for each row execute function boss_private.diamond_engine_identity();
alter function boss_private.games_append(uuid,uuid,text,uuid,jsonb,jsonb,uuid)rename to games_append_phase5e;
create function boss_private.games_append(p_game uuid,p_actor uuid,p_op text,p_request uuid,p_before jsonb,p_extra jsonb default'{}',p_correction uuid default null)returns uuid
language plpgsql security definer set search_path=''as $$
declare s public.game_diamond_states;begin
 select *into s from public.game_diamond_states where game_id=p_game;
 return boss_private.games_append_phase5e(p_game,p_actor,p_op,p_request,p_before,case when s.game_id is null then'{}'::jsonb else jsonb_build_object('diamond',s.state)end||p_extra,p_correction);
end$$;
alter function boss_private.games_command(uuid,text,jsonb,uuid,boolean,uuid)rename to games_command_phase5e;
create function boss_private.games_command(p_actor uuid,p_op text,i jsonb,p_request uuid,p_replay boolean default false,p_resource uuid default null)returns jsonb
language plpgsql security definer set search_path=''as $$
declare g public.games;e public.events;s public.game_diamond_states;begin
 if p_op like'diamond.%'then return boss_private.diamond_command(p_actor,p_op,i,p_request,p_replay);end if;
 if p_op in('game.score.set','game.score.reverse','game.roster.snapshot','game.finalize','game.reopen','game.start')or(p_op='game.transition'and i->>'status'='live')then
 select *into g from public.games where id=(i->>'game_id')::uuid;
 if exists(select 1 from public.game_diamond_states where game_id=g.id)then
 select *into e from public.events where id=g.event_id for update;select *into g from public.games where id=g.id for update;
 perform boss_private.games_lock_authority(p_actor,g);perform boss_private.games_require_live_auth();
 if p_actor is distinct from boss_private.require_admin_actor()or not boss_private.games_operation_allowed(p_actor,p_op,g)then raise exception 'Access denied'using errcode='PT403';end if;
 if p_op in('game.score.set','game.score.reverse','game.roster.snapshot')then raise exception 'Diamond owns score and roster'using errcode='PT409';end if;
 if not boss_private.games_feature(g.organization_id,g.sport_key||'_live_scoring')or not boss_private.games_feature(g.organization_id,'game_operations')then raise exception 'Access denied'using errcode='PT403';end if;
 select *into s from public.game_diamond_states where game_id=g.id;
 if p_op='game.finalize'and not p_replay and(not boss_private.diamond_final_ready(s.configuration,s.state)
 or s.roster_revision<>g.roster_revision or s.state is distinct from boss_private.diamond_rebuild(g.id)or g.primary_score<>(s.state->>'primary_score')::int or g.opponent_score<>(s.state->>'opponent_score')::int)then raise exception 'Diamond not ready to finalize'using errcode='PT409';end if;
 end if;end if;
 return boss_private.games_command_phase5e(p_actor,p_op,i,p_request,p_replay,p_resource);
end$$;
-- Every helper is private; the existing caller-bound native public RPC remains.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='boss_private'and(p.proname like'diamond_%'or p.proname in('games_append','games_append_phase5e','games_command','games_command_phase5e','tracking_selection','tracking_profile_command','games_configure','games_configuration','games_feature'))loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);end loop;end$$;

