insert into public.game_stat_catalog_items(sport_key,catalog_version,key,definition) values('baseball','boss-tracking-v1','runner_state','{"key":"runner_state","label":"runner state","short_label":"Runners","category":"game_state","classification":"required","available":true,"default_enabled":true,"modes":["action_first","player_first"],"dependencies":[],"actions":["advance"],"prompts":[],"order":2,"scopes":["game"],"quick_eligible":false}'::jsonb);
